// write via label
const writeRoot = page.frameLocator("iframe#accessible-frame").getByRole("form", { name: "Partial billing composer" })
const writeTarget = writeRoot.getByLabel("Billing note")
await expect(writeTarget).toBeVisible()
await expect(writeTarget).toBeEditable()
await expect(writeTarget).toHaveValue("Accessible draft note")
await writeTarget.fill(INPUT_TEXT)

// submit via role
const submitRoot = page.frameLocator("iframe#accessible-frame").getByRole("form", { name: "Partial billing composer" })
const submitTarget = submitRoot.getByRole("button", { name: "Save accessible draft" })
await expect(submitTarget).toBeVisible()
await expect(submitTarget).toBeEnabled()
await submitTarget.click()

// read via text
const readRoot = page.frameLocator("iframe#accessible-frame")
const readTarget = readRoot.getByText("Saved accessible draft")
await expect(readTarget).toBeVisible()
await expect(readTarget).toContainText("Saved accessible draft")
const readText = await readTarget.innerText()
